  /* ── часть 05 · app/05_live_map.js — карта местоположения ── */
  /* =====================================================================
     РЕНДЕР: КАРТА МЕСТОПОЛОЖЕНИЯ — все маршруты мастеров на сегодня
     Яндекс-карта + колонка мастеров справа. Для каждого мастера маршрут
     оптимизируется (OSRM trip). Автомобили двигаются ПО РАСПИСАНИЮ:
     выезд с базы в 8:30, время поездки = расчёт оптимизации маршрута,
     стоянка на объекте = человеко-часы задачи. Позиция машины — функция
     текущего времени: зайди в 11:00 — увидишь, где машины находятся сейчас.
     ===================================================================== */
  var LM_START_MIN = 8 * 60 + 30; // начало рабочего дня — 8:30
  var CAR_IMG_DATA = "data:image/png;base64,";
  var lmState = { ymap: null, token: 0, lastSig: null, refreshTimer: null, colls: {}, routes: {}, scheds: {}, cars: {}, marks: {}, labels: {}, poly: {}, dim: {}, hi: { mid: null, idx: -1 }, tick: null, virt: null, pageDate: null, clickDot: null };

  // Круглый SVG-маркер с номером (цвет мастера); ring=true — подсветка активного объекта
  function lmSvgIcon(txt, bg, size, ring) {
    size = size || 30;
    var c = size / 2, r = size / 2 - 2.5, fs = Math.round(size * 0.46);
    var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + size + '" height="' + size + '">' +
      (ring ? '<circle cx="' + c + '" cy="' + c + '" r="' + (r + 1.5) + '" fill="none" stroke="' + bg + '" stroke-width="2.5" opacity="0.5"/>' : '') +
      '<circle cx="' + c + '" cy="' + c + '" r="' + r + '" fill="' + bg + '" stroke="#ffffff" stroke-width="3"/>' +
      '<text x="50%" y="' + Math.round(c + fs * 0.36) + '" font-family="Arial,sans-serif" font-size="' + fs + '" font-weight="bold" fill="#ffffff" text-anchor="middle">' + txt + '</text></svg>';
    return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
  }

  // Размеры машины: картинка 252×519 (вид сверху, вытянута по вертикали) —
  // НЕ растягиваем в квадрат, сохраняем натуральные пропорции (уже с боков)
  var LM_CAR_W = 18, LM_CAR_H = 38;

  // Тёмная плашка с ФИО мастера (над машиной)
  function lmPlateIcon(name) {
    var w = Math.max(46, Math.round(name.length * 6.7) + 16), h = 20;
    var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + w + '" height="' + h + '">' +
      '<rect x="0.5" y="0.5" width="' + (w - 1) + '" height="' + (h - 1) + '" rx="4" fill="#0f2740" fill-opacity="0.92" stroke="rgba(255,255,255,.7)" stroke-width="1"/>' +
      '<text x="50%" y="' + Math.round(h / 2 + 4) + '" font-family="Segoe UI,Arial,sans-serif" font-size="11" font-weight="700" fill="#ffffff" text-anchor="middle">' + esc(name) + '</text></svg>';
    return { href: 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg), w: w, h: h };
  }

  // Азимут направления движения (0° = север)
  function lmBearing(lat1, lng1, lat2, lng2) {
    var PI = Math.PI, dLng = (lng2 - lng1) * PI / 180;
    var y = Math.sin(dLng) * Math.cos(lat2 * PI / 180);
    var x = Math.cos(lat1 * PI / 180) * Math.sin(lat2 * PI / 180) - Math.sin(lat1 * PI / 180) * Math.cos(lat2 * PI / 180) * Math.cos(dLng);
    return (Math.atan2(y, x) * 180 / PI + 360) % 360;
  }

  function lmFmtTime(min) {
    var h = Math.floor(min / 60), mm = Math.round(min % 60);
    return h + ':' + ('0' + mm).slice(-2);
  }

  // ===== Виртуальные часы симуляции =====
  // Идут 1:1 с реальным временем (+1 минута за минуту), но дату/время можно изменить кликом.
  function lmSetVirt(d) { lmState.virt = { baseReal: Date.now(), baseVirt: d.getTime() }; }
  function lmVirtNow() {
    if (!lmState.virt) lmState.virt = { baseReal: Date.now(), baseVirt: Date.now() };
    return new Date(lmState.virt.baseVirt + (Date.now() - lmState.virt.baseReal));
  }
  function lmIsoDate(d) { return d.getFullYear() + '-' + ('0' + (d.getMonth() + 1)).slice(-2) + '-' + ('0' + d.getDate()).slice(-2); }
  function lmHm(d) { return ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2) + ':' + ('0' + d.getSeconds()).slice(-2); }
  // Подпись выбранного дня: Сегодня / Завтра / Вчера / дата
  function lmDayLabel(off) {
    var d = offToDate(off), today = offToDate(0);
    var diff = Math.round((new Date(d.getFullYear(), d.getMonth(), d.getDate()) - new Date(today.getFullYear(), today.getMonth(), today.getDate())) / 86400000);
    var name = diff === 0 ? 'Сегодня' : diff === 1 ? 'Завтра' : diff === -1 ? 'Вчера' : '';
    return (name ? name + ', ' : '') + d.getDate() + ' ' + MON[d.getMonth()] + (name ? '' : ' ' + d.getFullYear());
  }

  function renderLiveMap(force) {
    var view = document.getElementById('view');
    var dayOff = (S.lmDay != null) ? S.lmDay : 0; // выбранный день (0 = сегодня)
    if (!lmState.virt) lmSetVirt(new Date()); // виртуальные часы = реальные (идут 1:1)
    // --- Данные: мастера с задачами выбранного дня ---
    // roleMasters (а НЕ visibleMasters): на карте местоположения ВСЕГДА все участки —
    // выбранный на панели мониторинга участок здесь не действует
    var masters = roleMasters();
    var todayByMaster = {};
    masters.forEach(function (m) {
      var ts = S.tasks.filter(function (t) { return t.m === m.id && t.d === dayOff && !isDone(t); });
      if (ts.length) todayByMaster[m.id] = ts;
    });
    var active = masters.filter(function (m) { return todayByMaster[m.id]; });

    // Сигнатура данных: авто-обновление не перестраивает карту, если ничего не изменилось
    var sig = active.map(function (m) {
      return m.id + ':' + todayByMaster[m.id].map(function (t) { return t.id + (t.s || t.status || ''); }).join(',');
    }).join('|');
    if (!force && sig === lmState.lastSig && lmState.ymap && document.getElementById('lm-map')) return;
    lmState.lastSig = sig;
    lmState.token++;
    var token = lmState.token;
    lmStopTicker();
    if (lmState.ymap) { try { lmState.ymap.destroy(); } catch (e) {} lmState.ymap = null; }
    lmState.colls = {};
    lmState.routes = {};
    lmState.scheds = {};
    lmState.cars = {};
    lmState.marks = {};
    lmState.labels = {};
    lmState.poly = {};
    lmState.hi = { mid: null, idx: -1 };
    lmState.clickDot = null;
    lmHideHintTip();

    var d0 = offToDate(dayOff);
    lmState.pageDate = lmIsoDate(d0);
    var base = currentBase();
    var totalTasks = 0, totalHours = 0;
    active.forEach(function (m) {
      todayByMaster[m.id].forEach(function (t) { totalTasks++; totalHours += taskHours(t); });
    });

    // --- Разметка ---
    var html = '<div id="lm-wrap" style="height:calc(100vh - 62px);display:flex;background:#e8eef3;overflow:hidden;position:relative;z-index:0">';
    html += '<style>@media(max-width:840px){#lm-side{position:absolute;top:0;right:0;bottom:0;width:270px;box-shadow:-6px 0 20px rgba(15,39,64,.18);z-index:30}}' +
      '#lm-date-inp::-webkit-calendar-picker-indicator,#lm-time-inp::-webkit-calendar-picker-indicator{display:none}' +
      '</style>';
    // Блок даты и времени симуляции: дата слева, время справа — только цифры
    // (клик по цифрам даты открывает календарь, по цифрам времени — выбор времени)
    html += '<div id="lm-clock-box" style="position:absolute;top:12px;left:calc((100% - 330px) / 2);transform:translateX(-50%);z-index:25;background:rgba(255,255,255,.97);border:1px solid var(--line);border-radius:14px;box-shadow:0 6px 22px rgba(15,39,64,.25);padding:9px 20px 7px;user-select:none">' +
      '<div style="display:flex;align-items:center;justify-content:center;gap:16px">' +
      '<input type="date" id="lm-date-inp" title="Календарь — смена даты" style="border:none;background:none;font-family:inherit;font-size:17px;font-weight:700;color:var(--ink);outline:none;cursor:pointer;width:118px;text-align:center">' +
      '<div style="width:1px;height:22px;background:var(--line);flex:0 0 auto"></div>' +
      '<input type="time" id="lm-time-inp" step="1" title="Выбор времени" style="border:none;background:none;font-family:inherit;font-size:17px;font-weight:700;color:var(--ink);outline:none;cursor:pointer;width:104px;text-align:center">' +
      '</div>' +
      '<button type="button" id="lm-now-btn" title="Сегодняшняя дата и текущее время — с точностью до секунд" style="margin-top:6px;width:100%;border:1px solid var(--line);background:var(--panel-3);border-radius:8px;font-family:inherit;font-size:12px;font-weight:700;color:var(--blue);cursor:pointer;padding:3px 8px">Сейчас</button>' +
      '</div>';
    html += '<div id="lm-map" style="flex:1;min-width:0;position:relative">';
    // Скелетон-загрузка: карта и маршруты строятся — shimmer вместо пустоты
    if (active.length) {
      html += '<div id="lm-loading" style="position:absolute;inset:0;z-index:4;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;background:var(--bg);transition:opacity .3s">' +
        '<div style="display:flex;gap:8px;align-items:center">' +
          '<div class="skel" style="width:120px;height:10px"></div><div class="skel" style="width:70px;height:10px"></div><div class="skel" style="width:90px;height:10px"></div>' +
        '</div>' +
        '<div class="skel" style="width:70%;height:14px"></div>' +
        '<div class="skel" style="width:55%;height:14px"></div>' +
        '<div class="skel" style="width:80%;height:14px"></div>' +
        '<div style="font-size:12.5px;font-weight:700;color:var(--muted);margin-top:6px">🚗 Строим маршруты…</div>' +
      '</div>';
    }
    if (!active.length) {
      html += '<div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:var(--panel-2);z-index:5;text-align:center;padding:20px">' +
        '<div><div style="font-size:40px;margin-bottom:10px">🗺</div><div style="font-weight:800;color:var(--ink)">На этот день маршрутов нет</div>' +
        '<div class="sub" style="margin-top:6px">Добавьте задачи на сегодняшнюю дату в «Планировании» — они появятся здесь автоматически.</div></div></div>';
    }
    html += '</div>';
    html += '<aside id="lm-side" style="flex:0 0 330px;border-left:1px solid var(--line);background:var(--card);display:flex;flex-direction:column;min-height:0">';
    html += '<div style="padding:12px 14px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:8px">' +
      '<div><div style="font-size:14px;font-weight:800;color:var(--ink)">🗺 Маршруты</div>' +
      '<div class="sub" style="font-size:12.5px">' + lmDayLabel(dayOff) + ' · 🚩 ' + esc(base.name) + '</div></div>' +
      '<div style="flex:1"></div><button class="btn sm" id="lm-refresh" title="Перестроить все маршруты">⟳ Обновить</button></div>';
    html += '<div style="padding:8px 14px;border-bottom:1px solid var(--line);font-size:12.5px;color:var(--muted)" id="lm-summary">' +
      (active.length ? '👨‍🔧 ' + active.length + ' ' + (active.length === 1 ? 'мастер' : 'мастеров') + ' · 📋 ' + totalTasks + ' задач · ⏱ ' + fmtH(totalHours) + ' ч' : 'Нет активных маршрутов') + '</div>';
    html += '<div id="lm-list" style="flex:1;overflow:auto;padding:8px">';
    if (!active.length) {
      html += '<div class="empty" style="padding:24px 10px;font-size:12.5px">У мастеров нет задач на сегодня.<br>Создайте задачи в разделе «Планирование / Календарь».</div>';
    }
    active.forEach(function (m) {
      var ts = todayByMaster[m.id];
      var hours = 0; ts.forEach(function (t) { hours += taskHours(t); });
      var color = m.color || '#2563eb';
      html += '<div class="lm-card" data-mid="' + esc(m.id) + '" style="padding:10px;border:1px solid var(--line);border-radius:10px;margin-bottom:8px;cursor:pointer;background:var(--card);transition:border-color .15s" title="Клик — показать маршрут на карте">' +
        '<div style="display:flex;align-items:center;gap:8px">' +
        '<input type="checkbox" class="lm-vis" data-mid="' + esc(m.id) + '" checked style="width:15px;height:15px;cursor:pointer;flex:0 0 auto" title="Скрыть маршрут — всё мастера станет на 70% прозрачным">' +
        '<span style="width:12px;height:12px;border-radius:3px;flex:0 0 auto;background:' + color + '"></span>' +
        '<b style="font-size:12.5px;color:var(--ink)">' + esc(m.name) + '</b>' +
        '<span style="font-size:12px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(m.area || '') + '</span></div>' +
        '<div style="font-size:12.5px;color:var(--muted);margin-top:4px">📋 ' + ts.length + ' ' + (ts.length === 1 ? 'задача' : 'задач') + ' · ⏱ ' + fmtH(hours) + ' ч</div>' +
        '<div class="lm-status" data-mid="' + esc(m.id) + '" style="font-size:12.5px;color:#2563eb;margin-top:2px">⏳ Строю маршрут (оптимизация)…</div>' +
        '<div class="lm-live" data-mid="' + esc(m.id) + '" style="font-size:12.5px;margin-top:2px;color:var(--ink)">⏳ Выезд в ' + lmFmtTime(LM_START_MIN) + '</div>' +
        '</div>';
    });
    html += '</div>';
    html += '<div style="padding:9px 14px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)">🚗 Выезд с базы в ' + lmFmtTime(LM_START_MIN) + ' · время поездки — по оптимизации маршрута · стоянка на объекте — человеко-часы задачи</div>';
    html += '</aside></div>';
    view.innerHTML = html;

    setTimeout(function () { lmHideLoading(); }, 12000); // страховка: скелетон не висит вечно
    var refreshBtn = document.getElementById('lm-refresh');
    if (refreshBtn) refreshBtn.addEventListener('click', function () { lmOsrmCacheClear(); renderLiveMap(true); }); // обновить = свежие данные от роутера

    // Смена даты: строим маршруты выбранного дня (время суток сохраняется)
    var dateInp = document.getElementById('lm-date-inp');
    if (dateInp) {
      dateInp.addEventListener('click', function () { try { dateInp.showPicker(); } catch (e) {} });
      dateInp.addEventListener('change', function () {
      var v = dateInp.value;
      if (!v) return;
      var p = v.split('-');
      var nd = new Date(parseInt(p[0], 10), parseInt(p[1], 10) - 1, parseInt(p[2], 10));
      var vt = lmVirtNow();
      lmSetVirt(new Date(nd.getFullYear(), nd.getMonth(), nd.getDate(), vt.getHours(), vt.getMinutes(), vt.getSeconds()));
      S.lmDay = dateToOff(nd);
        renderLiveMap(true);
      });
    }
    // Смена времени: машины мгновенно переставляются на новое время
    var timeInp = document.getElementById('lm-time-inp');
    if (timeInp) {
      timeInp.addEventListener('click', function () { try { timeInp.showPicker(); } catch (e) {} });
      timeInp.addEventListener('change', function () {
      var v = timeInp.value;
      if (!v) return;
      var p = v.split(':');
      var vt = lmVirtNow();
      lmSetVirt(new Date(vt.getFullYear(), vt.getMonth(), vt.getDate(), parseInt(p[0], 10), parseInt(p[1], 10), p[2] ? parseInt(p[2], 10) : 0));
        lmTick();
      });
    }

    // Кнопка «Сейчас»: сегодняшняя дата и текущее время (с точностью до секунд)
    var nowBtn = document.getElementById('lm-now-btn');
    if (nowBtn) nowBtn.addEventListener('click', function () {
      lmSetVirt(new Date());
      var vn = lmVirtNow();
      var newOff = dateToOff(new Date(vn.getFullYear(), vn.getMonth(), vn.getDate()));
      if (newOff !== ((S.lmDay != null) ? S.lmDay : 0)) {
        S.lmDay = newOff;
        renderLiveMap(true); // день сменился — строим маршруты сегодняшнего дня
      } else {
        lmTick(); // тот же день — мгновенно переставляем часы и машины
      }
    });

    // Клик по карточке — зум к маршруту мастера; чекбокс — показать/скрыть
    view.querySelectorAll('.lm-card').forEach(function (card) {
      card.addEventListener('click', function () {
        var mid = card.dataset.mid;
        var coll = lmState.colls[mid];
        if (lmState.ymap && coll && coll.getBounds()) {
          lmState.ymap.setBounds(coll.getBounds(), { checkZoomRange: true, duration: 300 });
        }
      });
    });
    view.querySelectorAll('.lm-vis').forEach(function (chk) {
      chk.addEventListener('click', function (e) { e.stopPropagation(); });
      chk.addEventListener('change', function (e) {
        e.stopPropagation();
        // «Скрыть» = маршрут, машина, плашка и адреса мастера становятся на 70% прозрачными
        lmApplyDim(chk.dataset.mid, !chk.checked);
      });
    });

    // --- Яндекс-карта ---
    function mapFail() {
      var mapEl = document.getElementById('lm-map');
      if (mapEl && token === lmState.token) {
        mapEl.insertAdjacentHTML('beforeend',
          '<div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:var(--panel-2);z-index:5;text-align:center;padding:20px">' +
          '<div><div style="font-size:34px;margin-bottom:8px">🛰</div><div style="font-weight:800;color:var(--ink);margin-bottom:4px">Не удалось загрузить Яндекс.Карту</div>' +
          '<div class="sub" style="margin-bottom:10px">Проверьте подключение к интернету и нажмите «Обновить».</div>' +
          '<button class="btn sm primary" id="lm-retry">⟳ Повторить</button></div></div>');
        var retry = document.getElementById('lm-retry');
        if (retry) retry.addEventListener('click', function () { renderLiveMap(true); });
      }
    }
    if (!active.length) return; // карта не нужна — пустое состояние

    ensureYandex(function () {
      if (token !== lmState.token || S.screen !== 'livemap') return;
      try {
        lmState.ymap = new ymaps.Map('lm-map', {
          center: [base.lat, base.lng], zoom: 11,
          controls: ['zoomControl', 'typeSelector', 'fullscreenControl', 'geolocationControl']
        }, { suppressMapOpenBlock: true });
      } catch (e) { mapFail(); return; }
      // Метка базы (прозрачна для кликов — как все метки на этой карте)
      lmState.ymap.geoObjects.add(new ymaps.Placemark([base.lat, base.lng], {}, {
        iconLayout: 'default#image',
        iconImageHref: lmSvgIcon('Б', '#0f2740', 30),
        iconImageSize: [30, 30], iconImageOffset: [-15, -15],
        hasBalloon: false, hasHint: false,
        interactivityModel: 'default#transparent'
      }));
      // ЕДИНСТВЕННЫЙ обработчик кликов: на уровне карты (не на объектах!).
      // Клик рядом с адресом → балун метки; клик по линии маршрута → «будет здесь».
      lmState.ymap.events.add('click', function (e) {
        try { lmRouteClick(e); } catch (err) { /* клик не может ломать страницу */ }
      });
      // Часы и позиции машин обновляются каждые 2 секунды
      lmStartTicker();

      // Последовательное построение маршрутов (бережём геокодер/OSRM)
      var queue = active.slice();
      (function next() {
        if (token !== lmState.token || S.screen !== 'livemap') return;
        var m = queue.shift();
        if (!m) return;
        lmBuildRoute(m, todayByMaster[m.id], base, token, function () { setTimeout(next, 350); });
      })();
    }, mapFail);
  }

  // Построение маршрута одного мастера: ТОЧКИ ЗАДАНИЙ ВСЕГДА на карте,
  // поверх — оптимизация OSRM trip + расписание дня
  /* ===== Кэш геометрии единого роутера BRouter car (economic) (sessionStorage) =====
     22.09-180: префикс ключей сменился на lmBr_ — старые числа OSRM из кэша не используются.
     Подпись = мастер + день + точки + база: повторное открытие карты
     местоположения не дёргает OSRM (лимиты!), маршруты появляются мгновенно.
     Кнопка «⟳ Обновить» сбрасывает кэш и берёт свежие данные. */
  function lmOsrmCacheKey(m, pts, base, dayOff) {
    if (dayOff == null) dayOff = (S.lmDay != null) ? S.lmDay : 0; // по умолчанию — день карты местоположения
    var s = m.id + '|' + dayOff + '|' + (base ? (+base.lat).toFixed(5) + ',' + (+base.lng).toFixed(5) : '');
    pts.forEach(function (p) { s += '|' + (+p.lat).toFixed(5) + ',' + (+p.lng).toFixed(5); });
    return 'lmBr_' + s; // 22.09-180: кэш единого роутера
  }
  function lmOsrmCached(m, pts, base, cb, dayOff) {
    var key = lmOsrmCacheKey(m, pts, base, dayOff);
    try {
      var raw = sessionStorage.getItem(key);
      if (raw) {
        var c = JSON.parse(raw);
        if (c && c.res && (Date.now() - c.ts) < 6 * 3600 * 1000) { cb(c.res); return; }
      }
    } catch (e) {}
    // 22.09-180: единый роутер BRouter car (economic) — те же числа, что на карте маршрутов
    brouterCarDayRoute(pts, base, function (res) {
      try { if (res && res.ok) sessionStorage.setItem(key, JSON.stringify({ ts: Date.now(), res: res })); } catch (e) {}
      cb(res);
    }, dayOff);
  }
  function lmOsrmCacheClear() {
    try {
      var del = [];
      // 22.09-180: чистим оба поколения кэша (старый OSRM и новый единого роутера)
      for (var i = 0; i < sessionStorage.length; i++) { var k = sessionStorage.key(i); if (k && (k.indexOf('lmBr_') === 0 || k.indexOf('lmOsrm_') === 0)) del.push(k); }
      del.forEach(function (k) { sessionStorage.removeItem(k); });
    } catch (e) {}
  }

  // Скрыть скелетон-загрузку карты местоположения (после первого маршрута)
  function lmHideLoading() {
    var el = document.getElementById('lm-loading');
    if (el) {
      el.style.opacity = '0';
      setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, 320);
    }
  }
  function lmBuildRoute(m, tasks, base, token, done) {
    var color = m.color || '#2563eb';
    var statusEl = document.querySelector('.lm-status[data-mid="' + m.id + '"]');
    var liveEl = document.querySelector('.lm-live[data-mid="' + m.id + '"]');
    var pts = tasks.map(function (t) {
      var o = OBJ_MAP[t.o];
      var w = workOf(t);
      return {
        id: t.id, addr: addrOf(t),
        lat: (t.lat != null) ? t.lat : (o ? o.lat : null),
        lng: (t.lng != null) ? t.lng : (o ? o.lng : null),
        work: w ? w.name : '?', hours: taskDurHours(t) // 22.09-223: стоянка = длительность (норма / исполнителей)
      };
    });
    // Коллекция сразу на карту — точки появятся ещё до готовности маршрута
    var coll = new ymaps.GeoObjectCollection();
    lmState.colls[m.id] = coll;
    lmState.marks[m.id] = [];
    if (lmState.ymap) lmState.ymap.geoObjects.add(coll);

    function drawMarkers(list) {
      lmState.marks[m.id].forEach(function (pmk) { try { coll.remove(pmk); } catch (e) {} });
      lmState.marks[m.id] = [];
      list.forEach(function (p, i) {
        if (p.lat == null || p.lng == null) return;
        // Метка «прозрачна» для кликов: балун Яндекса на любой метке этой карты
        // вызывал зависание. Информация об адресе — DOM-тултип (lmRouteClick).
        var pmk = new ymaps.Placemark([p.lat, p.lng], {}, {
          iconLayout: 'default#image',
          iconImageHref: lmSvgIcon(String(i + 1), color, 30),
          iconImageSize: [30, 30], iconImageOffset: [-15, -15],
          hasBalloon: false, hasHint: false,
          interactivityModel: 'default#transparent'
        });
        coll.add(pmk);
        lmState.marks[m.id].push(pmk);
      });
    }

    // Шаг 1: координаты точек — из задачи/справочника, недостающие геокодируем (Яндекс → Nominatim)
    var geoQueue = pts.filter(function (p) { return p.lat == null; });
    (function stepGeo() {
      if (token !== lmState.token) return; // страница перестроена
      var p = geoQueue.shift();
      if (!p) { afterGeo(); return; }
      geocodeAddressUnified(p.addr).then(function (c) {
        if (c) { p.lat = c.lat; p.lng = c.lng; }
        setTimeout(stepGeo, 300);
      });
    })();

    function afterGeo() {
      if (token !== lmState.token || S.screen !== 'livemap') return;
      var skipped = pts.filter(function (p) { return p.lat == null; }).length;
      var geoPts = pts.filter(function (p) { return p.lat != null; });
      if (!geoPts.length) {
        if (statusEl) { statusEl.innerHTML = '⚠ Координаты задач не найдены'; statusEl.style.color = 'var(--red)'; }
        if (liveEl) liveEl.innerHTML = '<span style="color:var(--muted)">⚠ Точки не определены</span>';
        if (done) done();
        return;
      }
      // Порядок: ближайший сосед от базы (затем OSRM trip оптимизирует)
      var remaining = geoPts.slice(), ordered = [], cur = base;
      while (remaining.length) {
        var bi = 0, bd = Infinity;
        for (var i = 0; i < remaining.length; i++) {
          var p = remaining[i];
          var d = (p.lat != null && p.lng != null) ? distKm(cur, p) : 1e9;
          if (d < bd) { bd = d; bi = i; }
        }
        var chosen = remaining.splice(bi, 1)[0];
        ordered.push(chosen);
        cur = chosen;
      }
      // Шаг 2: ТОЧКИ ЗАДАНИЙ — на карту сразу
      drawMarkers(ordered);
      if (statusEl) { statusEl.innerHTML = '📍 Точки на карте · оптимизирую маршрут…'; statusEl.style.color = '#2563eb'; }

      // Шаг 3: оптимизация маршрута + расписание (кэш OSRM — повторные входы без запросов)
      lmOsrmCached(m, ordered, base, function (res) {
        if (token !== lmState.token) return;
        var coords = (res.ok && res.geometry && res.geometry.length) ? res.geometry.map(function (c) { return [c[1], c[0]]; }) : null;
        // Оптимальный порядок объезда — по waypoints OSRM trip (как на карте маршрутов)
        var opt = ordered.slice();
        if (res.ok && res.waypoints && res.waypoints.length >= ordered.length + 1) {
          var wpOrder = [];
          for (var wi = 1; wi <= ordered.length; wi++) {
            if (res.waypoints[wi] && res.waypoints[wi].waypoint_index != null) wpOrder.push({ pt: ordered[wi - 1], pos: res.waypoints[wi].waypoint_index });
          }
          if (wpOrder.length === ordered.length) {
            wpOrder.sort(function (a, b) { return a.pos - b.pos; });
            opt = wpOrder.map(function (x) { return x.pt; });
          }
        }
        // перенумеруем метки по оптимизированному порядку
        var sameOrder = opt.length === ordered.length && opt.every(function (p, i) { return p === ordered[i]; });
        if (!sameOrder) drawMarkers(opt);
        // Линия маршрута. Полилиния «прозрачна» для событий (interactivityModel
        // default#transparent): клики по ней проходят СКВОЗЬ на карту, где их
        // ловит единственный обработчик lmRouteClick. Никаких подписок на события
        // самих полилиний — именно они вызывали зависание после нескольких кликов.
        if (coords) {
          var polyLine = new ymaps.Polyline(coords, {}, { strokeColor: color, strokeWidth: 5, strokeOpacity: 0.85, hasBalloon: false, hasHint: false, interactivityModel: 'default#transparent' });
          coll.add(polyLine);
          lmState.poly[m.id] = polyLine;
          lmAnimatePolyline(m.id, coords); // линия «прорисовывается» от базы к объектам
        }
        // Расписание + машина
        if (coords && coords.length > 1) {
          lmState.routes[m.id] = { coords: coords, name: m.name, km: res.km, color: color };
          lmBuildSchedule(m, opt, coords, res, base, color);
          lmEnsureCar(m.id);
          lmHideLoading(); // первый маршрут готов — убираем скелетон
          // Информация об адресах — в sch.stops; показывается DOM-тултипом
          // при клике (lmShowStopHint), балуны Яндекса не используются
        }
        if (statusEl) {
          if (coords) {
            statusEl.innerHTML = '🚗 <b>' + String(Math.round(res.km * 10) / 10).replace('.', ',') + ' км</b> · весь маршрут ~' + (res.jamMin || res.min) + ' мин' + (skipped ? ' · ⚠ ' + skipped + ' точка(и) без координат' : ''); // 22.09-180: время с пробками
            statusEl.style.color = 'var(--green)';
          } else {
            statusEl.innerHTML = '📍 Точки на карте · ⚠ ' + esc(res.msg || 'маршрут не построен');
            statusEl.style.color = 'var(--yellow)';
          }
        }
        if (!coords && liveEl) liveEl.innerHTML = '<span style="color:var(--yellow)">⚠ Симуляция недоступна — маршрут не построен</span>';
        if (done) done();
      });
    }
  }

  // Расписание дня мастера: чередование «поездка (мин из оптимизации) → стоянка (чел/часы задачи)»
  /* ЯДРО РАСПИСАНИЯ ДНЯ (чистая функция) — единый движок для карты
     местоположения И гант-шкалы дашборда: числа переездов всегда совпадают.
     Порядок объезда opt + результат OSRM (res.legs / res.km / res.min) →
     события дня (drive/stay), выезд с базы в 8:30 (LM_START_MIN),
     стоянка = человеко-часы задачи, последний переезд — возврат на базу. */
  function lmSchedCore(opt, res, polyKm) {
    var legs = (res && res.legs) || [];
    var nLegs = opt.length + 1; // база→1, 1→2, …, N→база
    // Время и километры каждого отрезка — из реальных отрезков маршрута OSRM
    // (как на «карте маршрутов»: одинаковый километраж = одинаковое время)
    var legKm = [], legMin = [], sumKm = 0;
    for (var l = 0; l < nLegs; l++) {
      var lk = (legs[l] && legs[l].distance != null) ? legs[l].distance / 1000 : ((res && res.km) || 0) / nLegs;
      var lv = (legs[l] && legs[l].duration != null) ? legs[l].duration / 60 : (((res && (res.jamMin || res.min)) || 0) / nLegs); // 22.09-180
      legKm.push(lk); legMin.push(Math.max(0.5, lv)); sumKm += lk;
    }
    var pk = polyKm || sumKm || 1e-9;
    var evs = [], accKm = 0, total = 0, accMin = 0, stops = [];
    for (var s = 0; s < nLegs; s++) {
      var km0 = accKm * pk / (sumKm || 1);
      accKm += legKm[s];
      var km1 = accKm * pk / (sumKm || 1);
      var dest = (s < opt.length) ? opt[s] : null; // null → возврат на базу
      evs.push({ type: 'drive', t0: LM_START_MIN + accMin, min: legMin[s], km0: Math.min(km0, pk), km1: Math.min(km1, pk), dest: dest });
      total += legMin[s]; accMin += legMin[s];
      if (s < opt.length) {
        var stayMin = Math.max(1, (opt[s].hours || 0) * 60); // стоянка = длительность задачи (чел.-часы / исполнителей, 22.09-223)
        evs.push({ type: 'stay', t0: LM_START_MIN + accMin, min: stayMin, pt: opt[s] });
        stops.push({ pt: opt[s], arriveMin: LM_START_MIN + accMin, untilMin: LM_START_MIN + accMin + stayMin, hours: opt[s].hours || 0 });
        total += stayMin; accMin += stayMin;
      }
    }
    return { evs: evs, stops: stops, total: total, legKm: legKm, legMin: legMin, sumKm: sumKm };
  }

  function lmBuildSchedule(m, opt, coords, res, base, color) {
    // Накопленные километры по полилинии (для позиции машины между объектами)
    var cum = [0];
    for (var i = 1; i < coords.length; i++) {
      cum.push(cum[i - 1] + distKm({ lat: coords[i - 1][0], lng: coords[i - 1][1] }, { lat: coords[i][0], lng: coords[i][1] }));
    }
    var polyKm = cum[cum.length - 1] || 1e-9;
    var core = lmSchedCore(opt, res, polyKm);
    lmState.scheds[m.id] = { evs: core.evs, stops: core.stops, coords: coords, cum: cum, polyKm: polyKm, total: core.total, name: m.name, color: color, base: base, km: res.km, pts: opt };
  }

  // Порядок объезда «ближайший сосед от базы» — как на карте местоположения (шаг 1)
  function lmNearestOrder(pts, base) {
    var remaining = pts.slice(), ordered = [], cur = base;
    while (remaining.length) {
      var bi = 0, bd = Infinity;
      for (var i = 0; i < remaining.length; i++) {
        var p = remaining[i];
        var d = (p.lat != null && p.lng != null) ? distKm(cur, p) : 1e9;
        if (d < bd) { bd = d; bi = i; }
      }
      var chosen = remaining.splice(bi, 1)[0];
      ordered.push(chosen);
      cur = chosen;
    }
    return ordered;
  }

  // Переупорядочивание точек по waypoint'ам OSRM (как на карте местоположения)
  function lmOrderByWaypoints(ordered, res) {
    var opt = ordered.slice();
    try {
      if (res && res.ok && res.waypoints && res.waypoints.length >= ordered.length + 1) {
        var wpOrder = [];
        for (var wi = 1; wi <= ordered.length; wi++) {
          if (res.waypoints[wi] && res.waypoints[wi].waypoint_index != null) wpOrder.push({ pt: ordered[wi - 1], pos: res.waypoints[wi].waypoint_index });
        }
        if (wpOrder.length === ordered.length) {
          wpOrder.sort(function (a, b) { return a.pos - b.pos; });
          opt = wpOrder.map(function (x) { return x.pt; });
        }
      }
    } catch (e) {}
    return opt;
  }

  // Точка на полилинии на заданном километре
  function lmPointAtKm(coords, cum, d) {
    var n = cum.length;
    if (d <= 0) return { c: coords[0], a: coords[0], b: coords[1] || coords[0] };
    if (d >= cum[n - 1]) return { c: coords[n - 1], a: coords[Math.max(0, n - 2)], b: coords[n - 1] };
    var i = 0;
    while (i < n - 2 && cum[i + 1] < d) i++;
    var segLen = (cum[i + 1] - cum[i]) || 1e-9;
    var f = (d - cum[i]) / segLen;
    var a = coords[i], b = coords[i + 1];
    return { c: [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f], a: a, b: b };
  }

  // Где машина должна быть в данный момент (минуты от полуночи)
  function lmPosAt(sch, nowMin) {
    var t = nowMin - LM_START_MIN;
    if (t < 0) return { state: 'before' };
    if (t >= sch.total) return { state: 'done', finishMin: LM_START_MIN + sch.total };
    var acc = 0;
    for (var i = 0; i < sch.evs.length; i++) {
      var ev = sch.evs[i];
      if (t < acc + ev.min) {
        if (ev.type === 'drive') {
          var f = (t - acc) / ev.min;
          var d = ev.km0 + (ev.km1 - ev.km0) * f;
          var pp = lmPointAtKm(sch.coords, sch.cum, d);
          return { state: 'drive', c: pp.c, a: pp.a, b: pp.b, dest: ev.dest, durMin: Math.max(1, Math.round(ev.min)), etaMin: LM_START_MIN + acc + ev.min };
        }
        return { state: 'stay', c: [ev.pt.lat, ev.pt.lng], pt: ev.pt, untilMin: LM_START_MIN + acc + ev.min };
      }
      acc += ev.min;
    }
    return { state: 'done', finishMin: LM_START_MIN + sch.total };
  }

  // Машина мастера — всегда на карте; над ней плашка с ФИО
  // (оба в коллекции маршрута: скрыл маршрут — всё становится полупрозрачным)
  function lmEnsureCar(mid) {
    if (!lmState.ymap || !lmState.routes[mid] || lmState.cars[mid]) return;
    try {
    var r = lmState.routes[mid];
    // Машина и плашка «прозрачны» для кликов (interactivityModel default#transparent):
    // балун у ДВИЖУЩЕЙСЯ метки (тикер двигает её каждую секунду) вызывал зависание
    // страницы. Клик по машине теперь проходит сквозь на карту — обработчик карты
    // показывает «автомобиль будет здесь ~HH:MM».
    var pm = new ymaps.Placemark(r.coords[0], {}, {
      iconLayout: 'default#image',
      iconImageHref: CAR_IMG_DATA,
      iconImageSize: [LM_CAR_W, LM_CAR_H],
      iconImageOffset: [-Math.round(LM_CAR_W / 2), -Math.round(LM_CAR_H / 2)],
      hasBalloon: false, hasHint: false,
      interactivityModel: 'default#transparent'
    });
    // Плашка с ФИО над машиной (тоже прозрачна для кликов)
    var plate = lmPlateIcon(r.name);
    var lbl = new ymaps.Placemark(r.coords[0], {}, {
      iconLayout: 'default#image',
      iconImageHref: plate.href,
      iconImageSize: [plate.w, plate.h],
      iconImageOffset: [-Math.round(plate.w / 2), -Math.round(LM_CAR_H / 2 + 6 + plate.h)],
      hasBalloon: false, hasHint: false,
      interactivityModel: 'default#transparent'
    });
    var coll = lmState.colls[mid];
    if (coll) { coll.add(pm); coll.add(lbl); }
    lmState.cars[mid] = pm;
    lmState.labels[mid] = lbl;
    lmCarAppear(pm, lbl, mid); // автомобиль появляется плавно (~2,4 с), как и маршрут
    if (lmState.dim[mid]) setTimeout(function () { lmApplyDim(mid, true); }, 400);
    } catch (e) {}
  }

  // Плавное появление автомобиля (~2,2 с): CSS-transition на DOM-элементе иконки —
  // масштаб 0.08→1 + прозрачность 0→1. ВАЖНО: иконка НЕ пересоздаётся (никаких
  // изменений iconImageSize/iconImageOffset — ymaps пересоздаёт элемент и мерцает);
  // transform/opacity на живом элементе плавны, не мешают тикеру (поворот машины —
  // на внутреннем элементе) и не конфликтуют со «скрытием маршрута» (dim).
  function lmCarAppear(pm, lbl, mid) {
    try {
      var token = lmState.token;
      var tries = 0;
      function getEl(p) {
        try { var ov = p.getOverlaySync ? p.getOverlaySync() : null; return (ov && ov.getElement) ? ov.getElement() : null; } catch (e) { return null; }
      }
      function start() {
        if (token !== lmState.token) return; // страница перестроена — не анимируем
        var el = getEl(pm);
        if (!el) {
          if (++tries < 40) setTimeout(start, 50); // элемент иконки появляется асинхронно
          return;
        }
        var t = lmState.dim[mid] ? 0.3 : 1; // скрытый маршрут — появление до 30%
        try {
          el.style.transition = 'none';
          el.style.transformOrigin = 'center center';
          el.style.transform = 'scale(0.08)';
          el.style.opacity = '0';
          void el.offsetWidth; // зафиксировать начальное состояние до включения transition
          el.style.transition = 'transform 2.2s cubic-bezier(.22,.61,.36,1), opacity 2.2s ease-out';
          el.style.transform = 'scale(1)';
          el.style.opacity = String(t);
          setTimeout(function () { try { el.style.transition = ''; } catch (e) {} }, 2400); // снять transition после появления
        } catch (e) {}
        if (lbl) {
          try {
            var lel = getEl(lbl);
            if (lel) {
              lel.style.transition = 'none';
              lel.style.opacity = '0';
              void lel.offsetWidth;
              lel.style.transition = 'opacity 2.2s ease-out';
              lel.style.opacity = String(t);
              setTimeout(function () { try { lel.style.transition = ''; } catch (e) {} }, 2400);
            }
          } catch (e) {}
        }
      }
      start();
    } catch (e) { /* появление не может ломать карту */ }
  }

  // Поворот машины по направлению движения (через DOM-элемент иконки)
  function lmRotateCar(pm, brg) {
    try {
      var ov = pm.getOverlaySync ? pm.getOverlaySync() : null;
      var el = ov && ov.getElement ? ov.getElement() : null;
      if (!el) return;
      var imgEl = el.querySelector('img');
      if (!imgEl) {
        // ymaps рендерит иконку <ymaps>-элементом с background-image — ищем его
        var kids = el.querySelectorAll('ymaps, div');
        for (var di = 0; di < kids.length; di++) {
          if ((kids[di].style.backgroundImage || '').indexOf('data:image/png') !== -1) { imgEl = kids[di]; break; }
        }
      }
      if (imgEl) {
        imgEl.style.transformOrigin = 'center center';
        imgEl.style.transform = brg == null ? 'none' : 'rotate(' + Math.round(brg) + 'deg)';
      }
    } catch (e) {}
  }

  // Кружок-метка в точке клика: точное местоположение, куда нажал пользователь.
  // Обычная метка без балуна и без событий («прозрачна») — безопасно.
  function lmDotIcon() {
    var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18">' +
      '<circle cx="9" cy="9" r="8" fill="rgba(37,99,235,.22)" stroke="#2563eb" stroke-width="2"/>' +
      '<circle cx="9" cy="9" r="3.5" fill="#2563eb" stroke="#ffffff" stroke-width="1.5"/></svg>';
    return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
  }
  var LM_DOT_HREF = null;
  // Убрать кружок клика (клик мимо маршрута — кружка быть не должно)
  function lmClearClickDot() {
    try {
      if (lmState.clickDot && lmState.ymap) lmState.ymap.geoObjects.remove(lmState.clickDot);
    } catch (e) { /* клик не может ломать страницу */ }
    lmState.clickDot = null;
  }
  function lmShowClickDot(lat, lng) {
    try {
      if (!lmState.ymap || !window.ymaps || !isFinite(lat) || !isFinite(lng)) return;
      lmClearClickDot();
      if (!LM_DOT_HREF) LM_DOT_HREF = lmDotIcon();
      lmState.clickDot = new ymaps.Placemark([lat, lng], {}, {
        iconLayout: 'default#image',
        iconImageHref: LM_DOT_HREF,
        iconImageSize: [18, 18],
        iconImageOffset: [-9, -9],
        hasBalloon: false, hasHint: false,
        interactivityModel: 'default#transparent',
        pane: 'overlaps'
      });
      lmState.ymap.geoObjects.add(lmState.clickDot);
    } catch (e) { /* клик не может ломать страницу */ }
  }

  // ЕДИНСТВЕННАЯ точка входа для кликов по карте (метки/линии прозрачны для событий):
  //  клик по адресу → карточка объекта (прибытие + работы), по базе → «База»,
  //  по линии маршрута → «автомобиль будет здесь ~HH:MM». Всё — DOM-тултипом;
  //  балуны Яндекс.Карт на этой странице не используются ВООБЩЕ (они зависали).
  //  Кружок клика ставится ТОЛЬКО при попадании в маршрут (адрес/база/линия);
  //  клик мимо маршрута — ни кружка, ни подсказки.
  function lmRouteClick(e) {
    lmHideHintTip(); // предыдущую подсказку закрываем любым кликом
    var c = (e && e.get) ? e.get('coords') : null;
    if (!c || c[0] == null || !isFinite(c[0]) || !isFinite(c[1])) return;
    var lat = c[0], lng = c[1];
    // радиусы в градусах — от масштаба карты (~18px вокруг метки, ~12px вокруг линии)
    var zoom = (lmState.ymap && lmState.ymap.getZoom) ? lmState.ymap.getZoom() : 11;
    var mPerPx = 156543.03392 * Math.cos(lat * Math.PI / 180) / Math.pow(2, zoom);
    var stopR = 18 * mPerPx / 111320, routeR = 12 * mPerPx / 111320;
    // 1) ближайший адрес (остановка маршрута).
    // Скрытые галочкой маршруты (lmState.dim) НЕ перехватывают клики: если линии
    // двух машин накладываются и одна скрыта, клик показывает именно ВИДИМУЮ машину
    var bestStop = null, bestStopD2 = stopR * stopR;
    for (var mid in lmState.scheds) {
      if (lmState.dim[mid]) continue; // скрытый маршрут — клики проходят мимо
      var s = lmState.scheds[mid];
      if (!s || !s.stops) continue;
      for (var p = 0; p < s.stops.length; p++) {
        var st = s.stops[p];
        if (!st.pt || st.pt.lat == null || st.pt.lng == null) continue;
        var dyS = st.pt.lat - lat, dxS = st.pt.lng - lng, d2S = dyS * dyS + dxS * dxS;
        if (d2S < bestStopD2) { bestStopD2 = d2S; bestStop = { mid: mid, idx: p }; }
      }
    }
    if (bestStop) {
      lmShowClickDot(lat, lng); // кружок — попали в метку адреса маршрута
      lmShowStopHint(bestStop.mid, bestStop.idx, e);
      return;
    }
    // 2) база (тоже только у нескрытых маршрутов)
    for (var mB in lmState.scheds) {
      if (lmState.dim[mB]) continue;
      var sb = lmState.scheds[mB];
      if (sb && sb.base && sb.base.lat != null) {
        var dyB = sb.base.lat - lat, dxB = sb.base.lng - lng;
        if (dyB * dyB + dxB * dxB < stopR * stopR) {
          lmShowClickDot(lat, lng); // кружок — попали в базу маршрута
          lmShowHintTip('🚩 База', esc(sb.base.name || ''), e);
          return;
        }
      }
    }
    // 3) ЛИНИЯ маршрута (расстояние до сегментов полилинии, не только до вершин)
    var hit = lmHitRouteLine(lat, lng, routeR);
    if (hit) {
      lmShowClickDot(hit.proj[0], hit.proj[1]); // кружок ТОЧНО на линии маршрута
      lmShowPointHint(hit.mid, hit.km, e);
      return;
    }
    // клик мимо маршрута → убираем прежний кружок, ничего не показываем
    lmClearClickDot();
  }

  // Попадание клика в линию маршрута: расстояние до каждого СЕГМЕНТА полилинии
  // (проекция точки на отрезок). Чистая математика, без API Яндекс.Карт.
  // Возвращает {mid, proj:[lat,lng], km} ближайшей точки линии внутри routeR,
  // иначе null. km — километраж проекции (интерполяция по сегменту).
  function lmHitRouteLine(lat, lng, routeR) {
    var best = null, bestD2 = routeR * routeR;
    var kx = Math.cos(lat * Math.PI / 180); // 1° долготы короче 1° широты
    for (var mid in lmState.scheds) {
      if (lmState.dim[mid]) continue; // скрытый маршрут не отвечает на клики (при наложении линий клик — по видимой машине)
      var s = lmState.scheds[mid];
      if (!s || !s.coords || s.coords.length < 2 || !s.cum) continue;
      for (var i = 1; i < s.coords.length; i++) {
        var a = s.coords[i - 1], b = s.coords[i];
        if (!a || !b || !isFinite(a[0]) || !isFinite(a[1]) || !isFinite(b[0]) || !isFinite(b[1])) continue;
        // клик — начало координат; координаты вершин в «поправленных» градусах
        var ax = (a[1] - lng) * kx, ay = a[0] - lat;
        var bx = (b[1] - lng) * kx, by = b[0] - lat;
        var abx = bx - ax, aby = by - ay;
        var len2 = abx * abx + aby * aby;
        var t = len2 > 1e-15 ? -(ax * abx + ay * aby) / len2 : 0;
        t = Math.max(0, Math.min(1, t));
        var px = ax + t * abx, py = ay + t * aby;
        var d2 = px * px + py * py;
        if (d2 < bestD2) {
          bestD2 = d2;
          var km = (isFinite(s.cum[i - 1]) && isFinite(s.cum[i]))
            ? s.cum[i - 1] + t * (s.cum[i] - s.cum[i - 1]) : s.cum[i];
          best = { mid: mid, proj: [a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1])], km: km };
        }
      }
    }
    return best;
  }

  // Карточка адреса (DOM-тултип): прибытие автомобиля + длительность работ
  function lmShowStopHint(mid, idx, evt) {
    try {
      var sch = lmState.scheds[mid];
      var st = sch && sch.stops[idx];
      if (!st || !st.pt) return;
      lmShowHintTip('№' + (idx + 1) + ' · ' + st.pt.addr,
        '🚗 Автомобиль прибудет ~<b>' + lmFmtTime(st.arriveMin) + '</b><br>' +
        '🔧 Работы: <b>' + fmtH(st.hours) + ' ч</b> (до ' + lmFmtTime(st.untilMin) + ')<br>' +
        (st.pt.work ? esc(st.pt.work) + '<br>' : '') +
        'Мастер: ' + esc(sch.name), evt);
    } catch (e) { /* клик не может ломать страницу */ }
  }

  // Клик по линии маршрута: во сколько автомобиль будет в этой точке.
  // km — километраж точки на полилинии (проекция клика, считает lmHitRouteLine).
  // МАКСИМАЛЬНАЯ ЗАЩИТА: чистая математика + обычный DOM-элемент поверх страницы.
  // Никаких вызовов balloon/placemark API Яндекс.Карт по клику — зависание исключено.
  function lmShowPointHint(mid, km, evt) {
    try {
      var sch = lmState.scheds[mid];
      if (!sch || !sch.evs || !sch.evs.length) return;
      if (!isFinite(km) || km < 0) return;
      // время прохода этого километра по расписанию
      var txt = null;
      for (var k = 0; k < sch.evs.length; k++) {
        var ev = sch.evs[k];
        if (ev.type !== 'drive' || !isFinite(ev.km0) || !isFinite(ev.km1)) continue;
        if (km < ev.km0 - 1e-9 || km > ev.km1 + 1e-9) continue;
        var segLen = ev.km1 - ev.km0;
        var f = segLen > 1e-9 ? (km - ev.km0) / segLen : 0;
        f = Math.max(0, Math.min(1, f));
        var t = ev.t0 + f * ev.min;
        txt = (isFinite(t) && t >= 0 && t < 1440) ? lmFmtTime(t) : null;
        break;
      }
      if (!txt) return;
      lmShowHintTip('🚗 ' + sch.name, 'Автомобиль будет здесь ~<b>' + txt + '</b>', evt);
    } catch (e) { /* клик по карте не может ломать страницу */ }
  }

  // DOM-тултип подсказки (обычный div поверх страницы; без API Яндекс.Карт)
  function lmShowHintTip(header, bodyHtml, evt) {
    lmHideHintTip();
    var tip = document.createElement('div');
    tip.id = 'lm-hint-tip';
    tip.style.cssText = 'position:fixed;z-index:1200;background:var(--card);border:1px solid var(--line);border-radius:12px;box-shadow:0 8px 28px rgba(15,39,64,.3);padding:10px 30px 10px 13px;font-family:inherit;font-size:12.5px;color:var(--ink);max-width:270px;line-height:1.45';
    tip.innerHTML = '<div style="font-weight:800;font-size:12px;color:var(--navy);margin-bottom:2px">' + header + '</div>' + bodyHtml +
      '<button type="button" title="Закрыть" style="position:absolute;top:4px;right:7px;border:none;background:none;cursor:pointer;font-size:15px;color:#64748b;font-family:inherit;line-height:1">×</button>';
    document.body.appendChild(tip);
    // позиция: пиксели клика (если есть), иначе — низ карты по центру
    var x = null, y = null;
    try {
      var pos = (evt && evt.get) ? evt.get('position') : null;
      if (pos && isFinite(pos[0]) && isFinite(pos[1])) { x = pos[0]; y = pos[1]; }
    } catch (e) {}
    var mapEl = document.getElementById('lm-map');
    if (x == null && mapEl) {
      var r = mapEl.getBoundingClientRect();
      x = r.left + r.width / 2; y = r.bottom - 80;
    }
    if (x == null) { x = window.innerWidth / 2; y = window.innerHeight - 90; }
    var w = tip.offsetWidth || 230, h = tip.offsetHeight || 52;
    x = Math.max(8, Math.min(window.innerWidth - w - 8, x - w / 2));
    y = Math.max(8, y - h - 16);
    if (y + h > window.innerHeight - 8) y = Math.max(8, window.innerHeight - h - 8);
    tip.style.left = Math.round(x) + 'px';
    tip.style.top = Math.round(y) + 'px';
    tip.querySelector('button').addEventListener('click', function (e) { e.stopPropagation(); lmHideHintTip(); });
    // клик в любом другом месте — закрыть (обычный DOM-слушатель, не ymaps)
    setTimeout(function () {
      function closer(ev) {
        if (ev && ev.target && tip.contains(ev.target)) return;
        lmHideHintTip();
        document.removeEventListener('click', closer, true);
      }
      document.addEventListener('click', closer, true);
    }, 60);
    lmState.hintTipTimer = setTimeout(lmHideHintTip, 15000); // автоскрытие
  }
  function lmHideHintTip() {
    if (lmState.hintTipTimer) { clearTimeout(lmState.hintTipTimer); lmState.hintTipTimer = null; }
    var t = document.getElementById('lm-hint-tip');
    if (t) t.remove();
  }

  // Подсветка метки объекта, на котором сейчас стоит машина (кольцо + увеличение)
  function lmHighlight(mid, idx) {
    if (lmState.hi.mid === mid && lmState.hi.idx === idx) return;
    // снять старую подсветку
    if (lmState.hi.mid && lmState.marks[lmState.hi.mid] && lmState.marks[lmState.hi.mid][lmState.hi.idx]) {
      var oldPm = lmState.marks[lmState.hi.mid][lmState.hi.idx];
      var oldColor = (lmState.scheds[lmState.hi.mid] || {}).color || '#2563eb';
      oldPm.options.set('iconImageHref', lmSvgIcon(String(lmState.hi.idx + 1), oldColor, 30));
      oldPm.options.set('iconImageSize', [30, 30]);
      oldPm.options.set('iconImageOffset', [-15, -15]);
    }
    lmState.hi = { mid: mid, idx: idx };
    if (mid && lmState.marks[mid] && lmState.marks[mid][idx]) {
      var pmk = lmState.marks[mid][idx];
      var col = (lmState.scheds[mid] || {}).color || '#2563eb';
      pmk.options.set('iconImageHref', lmSvgIcon(String(idx + 1), col, 40, true));
      pmk.options.set('iconImageSize', [40, 40]);
      pmk.options.set('iconImageOffset', [-20, -20]);
    }
  }

  // Прозрачность DOM-элемента иконки (для меток/машин/плашек)
  function lmDomOpacity(pmk, k) {
    if (!pmk) return;
    try { pmk.options.set('opacity', k); } catch (e) {}
    try {
      var ov = pmk.getOverlaySync ? pmk.getOverlaySync() : null;
      var el = ov && ov.getElement ? ov.getElement() : null;
      if (el) el.style.opacity = k;
    } catch (e) {}
  }

  // «Скрыть маршрут»: линия, машина, плашка и адреса мастера → 70% прозрачности (opacity 0.3)
  // Анимация «прорисовки» линии маршрута: полилиния плавно растёт от базы к
  // объектам (~0,9 с). Ограниченное число шагов обновления geometry (не каждый
  // кадр) — тикер/карта не нагружаются; при перестройке страницы анимация
  // останавливается сама (проверка токена).
  function lmAnimatePolyline(mid, coords) {
    try {
      var poly = lmState.poly[mid];
      if (!poly || !coords || coords.length < 3) return;
      var token = lmState.token;
      var steps = Math.min(24, Math.max(6, Math.round(coords.length / 4)));
      var n = 0;
      poly.geometry.setCoordinates([coords[0]]);
      var iv = setInterval(function () {
        try {
          if (token !== lmState.token || !lmState.poly[mid]) { clearInterval(iv); return; }
          n++;
          var upto = Math.min(coords.length, Math.max(2, Math.round(coords.length * n / steps)));
          lmState.poly[mid].geometry.setCoordinates(coords.slice(0, upto));
          if (n >= steps) {
            lmState.poly[mid].geometry.setCoordinates(coords); // финал — полная линия
            clearInterval(iv);
          }
        } catch (e) { clearInterval(iv); }
      }, 40);
    } catch (e) { /* анимация не может ломать карту */ }
  }

  function lmApplyDim(mid, on) {
    lmState.dim[mid] = !!on;
    var k = on ? 0.3 : 1;
    if (lmState.poly[mid]) {
      try { lmState.poly[mid].options.set('strokeOpacity', on ? 0.85 * 0.3 : 0.85); } catch (e) {}
    }
    lmDomOpacity(lmState.cars[mid], k);
    lmDomOpacity(lmState.labels[mid], k);
    (lmState.marks[mid] || []).forEach(function (pmk) { lmDomOpacity(pmk, k); });
    var card = document.querySelector('.lm-card[data-mid="' + mid + '"]');
    if (card) card.style.opacity = on ? 0.55 : 1;
  }

  // Тикер: каждые 2 секунды ставит машины туда, где они должны быть СЕЙЧАС
  function lmTick() {
    if (!lmState.ymap || S.screen !== 'livemap') return;
    try {
    var now = lmVirtNow(); // виртуальные часы (идут 1:1 с реальными, можно сменить кликом)
    var nowMin = now.getHours() * 60 + now.getMinutes() + now.getSeconds() / 60;
    // блок даты/времени (не трогаем поля, пока пользователь их редактирует)
    var dInp = document.getElementById('lm-date-inp');
    var tInp = document.getElementById('lm-time-inp');
    if (dInp && document.activeElement !== dInp) dInp.value = lmIsoDate(now);
    if (tInp && document.activeElement !== tInp) tInp.value = lmHm(now);
    // виртуальные часы перешли полночь → строим маршруты нового дня.
    // ВАЖНО: рекурсия lmTick → renderLiveMap → lmStartTicker → lmTick недопустима —
    // перестройка откладывается (setTimeout) и зацикливание исключено флагом.
    var isoNow = lmIsoDate(now);
    if (lmState.pageDate && isoNow !== lmState.pageDate && !lmState.daySwitching) {
      lmState.daySwitching = true;
      S.lmDay = dateToOff(new Date(now.getFullYear(), now.getMonth(), now.getDate()));
      // виртуальные часы жёстко привязываем к выбранному дню (страховка согласованности)
      lmSetVirt(new Date(now.getFullYear(), now.getMonth(), now.getDate(), now.getHours(), now.getMinutes(), now.getSeconds()));
      setTimeout(function () {
        lmState.daySwitching = false;
        if (S.screen === 'livemap') renderLiveMap(true);
      }, 0);
      return;
    }
    Object.keys(lmState.scheds).forEach(function (mid) {
      var sch = lmState.scheds[mid];
      var pos = lmPosAt(sch, nowMin);
      if (!lmState.cars[mid]) lmEnsureCar(mid);
      var pm = lmState.cars[mid];
      var liveEl = document.querySelector('.lm-live[data-mid="' + mid + '"]');
      var body = '';
      var lbl = lmState.labels[mid];
      if (pos.state === 'before') {
        lmHighlight(null, -1);
        if (pm) { pm.geometry.setCoordinates([sch.base.lat, sch.base.lng]); lmRotateCar(pm, null); }
        if (lbl) lbl.geometry.setCoordinates([sch.base.lat, sch.base.lng]);
        if (liveEl) liveEl.innerHTML = '<span style="color:var(--muted)">⏳ Выезд в ' + lmFmtTime(LM_START_MIN) + '</span>';
      } else if (pos.state === 'drive') {
        lmHighlight(null, -1);
        if (pm) { pm.geometry.setCoordinates(pos.c); lmRotateCar(pm, lmBearing(pos.a[0], pos.a[1], pos.b[0], pos.b[1])); }
        if (lbl) lbl.geometry.setCoordinates(pos.c);
        var destName = pos.dest ? pos.dest.addr : 'на базу';
        if (liveEl) liveEl.innerHTML = '🚗 <b>Едет</b>: ' + esc(destName) + ' — ~' + pos.durMin + ' мин в пути, прибытие ~' + lmFmtTime(pos.etaMin);
        body = 'Едет: ' + destName + ' (прибытие ~' + lmFmtTime(pos.etaMin) + ')';
      } else if (pos.state === 'stay') {
        if (pm) pm.geometry.setCoordinates(pos.c);
        if (lbl) lbl.geometry.setCoordinates(pos.c);
        lmHighlight(mid, sch.pts.indexOf(pos.pt)); // подсветить объект, где стоит машина
        if (liveEl) liveEl.innerHTML = '🔧 <b>На объекте</b>: ' + esc(pos.pt.addr) + ' — до ' + lmFmtTime(pos.untilMin) + ' (' + fmtH(pos.pt.hours) + ' ч работ)';
        body = 'На объекте: ' + pos.pt.addr + ' — работы до ' + lmFmtTime(pos.untilMin);
      } else {
        lmHighlight(null, -1);
        if (pm) { pm.geometry.setCoordinates([sch.base.lat, sch.base.lng]); lmRotateCar(pm, null); }
        if (lbl) lbl.geometry.setCoordinates([sch.base.lat, sch.base.lng]);
        if (liveEl) liveEl.innerHTML = '🏁 <b>Маршрут завершён</b> (~' + lmFmtTime(pos.finishMin) + ')';
        body = 'Маршрут завершён (~' + lmFmtTime(pos.finishMin) + ')';
      }
      // балун машины больше не используется (движущаяся метка + балун = зависание);
      // информация о машине — в колонке справа (живой статус)
      // если маршрут скрыт — новые/пересозданные объекты тоже делаем полупрозрачными
      if (lmState.dim[mid]) {
        lmDomOpacity(pm, 0.3);
        lmDomOpacity(lmState.labels[mid], 0.3);
        (lmState.marks[mid] || []).forEach(function (pmk) { lmDomOpacity(pmk, 0.3); });
      }
    });
    } catch (e) { /* тик не должен ронять страницу */ }
  }

  function lmStartTicker() {
    lmStopTicker();
    setTimeout(lmTick, 30); // НЕ синхронно: lmTick может перестроить страницу (полночь) — иначе рекурсия
    lmState.tick = setInterval(lmTick, 1000); // каждую секунду — секунды тикают плавно
  }
  function lmStopTicker() {
    if (lmState.tick) { clearInterval(lmState.tick); lmState.tick = null; }
  }

